/* @autogenerated */
/** Forma de `config/<env>-config.json`. Cada sección existe siempre: si el fichero no la trae, llega vacía. */
export interface AppConfig {
  /** Nombre del entorno (`environment.name`). */
  name: string;
  meta: MetaConfig;
  /** Una entrada por host lógico de API. */
  api: Record<string, ApiConfig>;
  i18n: I18nConfig;
  tenant: TenantConfig;
  /** Una entrada por identidad (`main`, …). */
  identity: Record<string, IdentityConfig>;
  telemetry: TelemetryConfig;
  theme: ThemeConfig;
  layout: Record<string, unknown>;
  data: DataConfig;
  actions: ActionsConfig;
}

/**
 * Contenido de `config/<env>-config.json`: todas las secciones son opcionales y `name` viene del entorno.
 * De aquí sale `public/config/phylax-config.schema.json` (`npm run config:schema`).
 */
export type AppConfigFile = Partial<Omit<AppConfig, 'name'>> & {
  /** Ruta al JSON Schema, para que el IDE autocomplete y valide. */
  $schema?: string;
};

export interface MetaConfig {
  title?: string;
}

/** Marca que se puede sustituir por tenant: logo y nombre del producto. */
export interface BrandConfig {
  /** Logo del menú. Relativo a la raíz de la app (`assets/img/logo.png`) o URL absoluta. */
  logo?: string;
  /** Logo para el modo oscuro; si falta, se usa `logo`. */
  'logo-dark'?: string;
  /** Nombre junto al logo; si falta, se usa `meta.title`. */
  'product-name'?: string;
}

export interface ThemeTenantConfig extends BrandConfig {
  /** Se aplican encima de `theme.tokens` cuando este tenant está activo. */
  tokens?: Record<string, string>;
}

export interface ThemeConfig extends BrandConfig {
  /** Modo por defecto hasta que el usuario elige uno. Por defecto `auto` (sigue al sistema). */
  mode?: 'auto' | 'light' | 'dark';
  /** Custom properties que se fijan en `<html>`: `{ "--mat-sys-primary": "#6750a4" }`. */
  tokens?: Record<string, string>;
  /** Overrides por tenant (`theme.tenants.<tenant>`). */
  tenants?: Record<string, ThemeTenantConfig>;
}

export interface ApiConfig {
  url?: string;
  identity?: string;
  headers?: Record<string, string>;
  'inject-context'?: string[];
}

export interface I18nConfig {
  'default-lang'?: string;
  'available-langs'?: string[];
}

export interface TenantConfig {
  default?: string;
}

export interface IdentityConfig {
  type: string;
  issuer?: string;
  url?: string;
  profile?: string;
  redirect?: string;
  'logout-redirect'?: string;
  'client-id'?: string;
  scope?: string;
  'roles-claim'?: string;
  audience?: string | string[];
  'force-https'?: boolean;
  persistent?: boolean;
  debug?: boolean;
  /** @deprecated PKCE siempre está activo: se ignora con un aviso. */
  pkce?: unknown;
  [extra: string]: unknown;
}

export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

export interface TelemetryConfig {
  /** Sin `name` no se arranca la telemetría. */
  name?: string;
  /** Entorno de despliegue (`deployment.environment.name`): dev, pre, pro… */
  environment?: string;
  exporter?: {
    tracer?: { url: string };
    logger?: { url: string };
  };
  logger?: {
    /** Nivel mínimo que se registra. Por defecto `info`. */
    level?: LogLevel;
    /** Reenvía también `console.*` al colector. Por defecto `false`. */
    'capture-console'?: boolean;
  };
}

export interface DataConfig {
  'token-wait-ms'?: number;
  /** Vida (ms) de la caché de los repositorios; `RepositoryMetadata.ttl` la sustituye por entidad. Por defecto 3000. */
  'cache-ttl'?: number;
  /**
   * Convierte a `Date` cualquier string con forma de fecha ISO en todas las respuestas. Por defecto `false`:
   * los repositorios convierten solo los campos que sus metadatos declaran como fecha.
   */
  'convert-iso-dates'?: boolean;
}

/**
 * Roles que ven una acción general, en todas las entidades o en una concreta. `*` la deja a todo el mundo y una lista
 * vacía la oculta; sin la clave la ve todo el mundo. Siempre manda además el ACL del backend.
 */
export interface ActionRolesConfig {
  /** Roles para todas las entidades. */
  roles?: string[];
  /** Roles de una entidad (`identity.user`); sustituyen a `roles`. */
  entities?: Record<string, string[]>;
}

/** Quién ve las acciones de importar y exportar a Excel que se generan para cada entidad. */
export interface ActionsConfig {
  import?: ActionRolesConfig;
  export?: ActionRolesConfig;
}

/** Configuración sin cargar: todas las secciones vacías. */
export function emptyConfig(name: string): AppConfig {
  return {
    name,
    meta: {},
    api: {},
    i18n: {},
    tenant: {},
    identity: {},
    telemetry: {},
    theme: {},
    layout: {},
    data: {},
    actions: {},
  };
}

// Rutas tipadas: 'meta.title', 'identity.main', 'identity.main.issuer', 'telemetry.logger.level'…
type Prev = [never, 0, 1, 2, 3, 4];

type PathsOf<T, D extends number> = [D] extends [never]
  ? never
  : T extends readonly unknown[]
    ? never
    : T extends object
      ? {
          [K in keyof T & string]: string extends keyof NonNullable<T[K]>
            ? K | `${K}.${string}`
            : NonNullable<T[K]> extends object
              ? K | `${K}.${PathsOf<NonNullable<T[K]>, Prev[D]>}`
              : K;
        }[keyof T & string]
      : never;

type ValueAt<T, P extends string> = P extends `${infer K}.${infer R}`
  ? K extends keyof T
    ? ValueAt<NonNullable<T[K]>, R>
    : never
  : P extends keyof T
    ? T[P]
    : never;

export type ConfigPath = PathsOf<AppConfig, 4>;
export type ConfigPathValue<P extends string> = ValueAt<AppConfig, P>;

export function readPath<P extends ConfigPath>(config: AppConfig, path: P): ConfigPathValue<P> | undefined {
  let node: any = config;
  for (const part of path.split('.')) {
    node = node == null ? undefined : node[part];
  }
  return node;
}
